package com.hsm.account.service;
import com.hsm.account.dto.*; import com.hsm.account.entity.*; import com.hsm.account.repository.*; import com.hsm.common.ApiException; import com.hsm.integration.EmailService; import com.hsm.security.SessionService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.security.SecureRandom; import java.time.*;
@Service public class AccountService { private static final long OTP_TTL=300,RESEND_WAIT=60; private final UserRepository users;private final UserProfileRepository profiles;private final ReviewRepository reviews;private final PasswordEncoder encoder;private final EmailService email;private final SessionService sessions;private final SecureRandom random=new SecureRandom(); public AccountService(UserRepository u,UserProfileRepository p,ReviewRepository r,PasswordEncoder e,EmailService m,SessionService s){users=u;profiles=p;reviews=r;encoder=e;email=m;sessions=s;}
 @Transactional public void register(AuthDtos.RegisterRequest x){String e=x.email().trim().toLowerCase();if(users.findByEmailIgnoreCase(e).isPresent())throw new ApiException(409,"EMAIL_REGISTERED","This email is already registered. Please log in.");User u=new User();u.setEmail(e);u.setPasswordHash(encoder.encode(x.password()));String otp=String.format("%06d",random.nextInt(1_000_000));u.setOtpHash(encoder.encode(otp));u.setOtpExpiresAt(Instant.now().plusSeconds(OTP_TTL));u.setOtpSentAt(Instant.now());u=users.save(u);UserProfile p=new UserProfile(u,e.substring(0,Math.min(80,e.indexOf('@'))));profiles.save(p);email.sendVerificationCode(e,otp);}
 @Transactional public void verify(AuthDtos.VerifyRequest x){User u=users.findByEmailIgnoreCase(x.email()).orElseThrow(()->new ApiException(400,"INVALID_OTP","The verification code is invalid or expired."));if(u.getOtpFailedCount()>=5||u.getOtpExpiresAt()==null||u.getOtpExpiresAt().isBefore(Instant.now())||!encoder.matches(x.otp(),u.getOtpHash())){u.setOtpFailedCount(u.getOtpFailedCount()+1);users.save(u);throw new ApiException(400,"INVALID_OTP","The verification code is invalid or expired.");}u.setEmailVerifiedAt(Instant.now());u.setOtpHash(null);u.setOtpExpiresAt(null);u.setOtpFailedCount(0);users.save(u);}
 @Transactional public void resend(AuthDtos.EmailRequest x){User u=users.findByEmailIgnoreCase(x.email()).orElseThrow(()->new ApiException(404,"ACCOUNT_NOT_FOUND","Account not found."));if(u.getEmailVerifiedAt()!=null)throw new ApiException(409,"ALREADY_VERIFIED","This email is already verified.");if(u.getOtpSentAt()!=null&&u.getOtpSentAt().plusSeconds(RESEND_WAIT).isAfter(Instant.now()))throw new ApiException(429,"OTP_COOLDOWN","Please wait before requesting another code.");String otp=String.format("%06d",random.nextInt(1_000_000));u.setOtpHash(encoder.encode(otp));u.setOtpExpiresAt(Instant.now().plusSeconds(OTP_TTL));u.setOtpSentAt(Instant.now());u.setOtpFailedCount(0);users.save(u);email.sendVerificationCode(u.getEmail(),otp);}
 @Transactional public AuthDtos.LoginResponse login(AuthDtos.LoginRequest x){User u=users.findByEmailIgnoreCase(x.email()).orElseThrow(()->new ApiException(401,"INVALID_CREDENTIALS","Email or password is incorrect."));if(u.getStatus()==User.Status.LOCKED||u.getLoginLockedUntil()!=null&&u.getLoginLockedUntil().isAfter(Instant.now()))throw new ApiException(423,"ACCOUNT_LOCKED","Login is temporarily locked.");if(u.getPasswordHash()==null||!encoder.matches(x.password(),u.getPasswordHash())){u.setFailedLoginCount(u.getFailedLoginCount()+1);if(u.getFailedLoginCount()>=5){u.setLoginLockedUntil(Instant.now().plusSeconds(900));u.setFailedLoginCount(0);}users.save(u);throw new ApiException(401,"INVALID_CREDENTIALS","Email or password is incorrect.");}if(u.getEmailVerifiedAt()==null)throw new ApiException(403,"EMAIL_NOT_VERIFIED","Verify your email before logging in.");u.setFailedLoginCount(0);u.setLoginLockedUntil(null);u.setLastLoginAt(Instant.now());users.save(u);return new AuthDtos.LoginResponse(new AuthDtos.UserResponse(u.getId(),u.getEmail(),u.getRole().name(),true));}
 @Transactional public void changePassword(User u, AuthDtos.ChangePasswordRequest x){if(u.getPasswordHash()==null)throw new ApiException(409,"PASSWORD_NOT_AVAILABLE","This account does not have a password. Use password recovery instead.");if(!encoder.matches(x.currentPassword(),u.getPasswordHash()))throw new ApiException(400,"CURRENT_PASSWORD_INCORRECT","The current password is incorrect.");if(!x.newPassword().equals(x.confirmPassword()))throw new ApiException(400,"PASSWORD_CONFIRMATION_MISMATCH","The new passwords do not match.");if(encoder.matches(x.newPassword(),u.getPasswordHash()))throw new ApiException(400,"PASSWORD_UNCHANGED","The new password must be different from the current password.");u.setPasswordHash(encoder.encode(x.newPassword()));users.save(u);}
 @Transactional public User loginWithGoogle(String email,String subject){String normalized=email.trim().toLowerCase();User user=users.findByGoogleSubject(subject).orElseGet(()->users.findByEmailIgnoreCase(normalized).orElseGet(()->{User created=new User();created.setEmail(normalized);created.setGoogleSubject(subject);created.setEmailVerifiedAt(Instant.now());return users.save(created);}));if(user.getGoogleSubject()==null){user.setGoogleSubject(subject);}user.setEmailVerifiedAt(Instant.now());user.setLastLoginAt(Instant.now());user=users.save(user);if(!profiles.existsById(user.getId())){String localPart=normalized.substring(0,normalized.indexOf('@'));profiles.save(new UserProfile(user,localPart.substring(0,Math.min(80,localPart.length()))));}return user;}
 public String session(User u){return sessions.create(u);} public User require(String token){return sessions.require(token);} public void logout(String token){sessions.remove(token);}
 public ProfileDtos.ProfileResponse profile(Long id){UserProfile p=profiles.findById(id).orElseThrow(()->new ApiException(404,"PROFILE_NOT_FOUND","Profile not found."));var rs=reviews.findCompletedBySeller(id);Double avg=rs.isEmpty()?null:Math.round(rs.stream().mapToInt(Review::getRating).average().orElse(0)*100)/100.0;return new ProfileDtos.ProfileResponse(id,p.getNickname(),p.getAvatarUrl(),p.getCoverPhotoUrl(),p.getBio(),avg,rs.size(),null);}
 @Transactional public ProfileDtos.ProfileResponse update(Long id,ProfileDtos.UpdateProfileRequest x){UserProfile p=profiles.findById(id).orElseThrow(()->new ApiException(404,"PROFILE_NOT_FOUND","Profile not found."));p.setNickname(x.nickname());p.setBio(x.bio());p.touch();profiles.save(p);return profile(id);}
 @Transactional public ProfileDtos.ProfileResponse updateImage(Long id,String kind,String url){UserProfile p=profiles.findById(id).orElseThrow(()->new ApiException(404,"PROFILE_NOT_FOUND","Profile not found."));if(kind.equals("avatar"))p.setAvatarUrl(url);else p.setCoverPhotoUrl(url);p.touch();profiles.save(p);return profile(id);}
}
